using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static partial class StackHouse3DSigns{
public static Mesh BuildCoffeeOpenRoadside(bool detailed){var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");atlas=new Texture2D(2,2);atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(material.GetTexture("_BaseMap"))));var cream=ColorUV(new Color(1,.85f,.45f));var gold=ColorUV(new Color(1,.59f,.06f));var dark=ColorUV(new Color(.035f,.025f,.018f));var word=JsonUtility.FromJson<LetterContours>(File.ReadAllText(D+"/Coffee Letter Contours.json")).words[0];var points=word.loops.SelectMany(l=>l.points).ToArray();float x0=points.Min(p=>p.x),x1=points.Max(p=>p.x),y0=points.Min(p=>p.y),y1=points.Max(p=>p.y);float grid=detailed?.035f:.14f;var loops=word.loops.Select(l=>l.points.Select(p=>{var v=new Vector2(-((p.x-x0)/(x1-x0)-.5f)*10.5f,(.5f-(p.y-y0)/(y1-y0))*1.4f);return new Vector2(Mathf.Round(v.x/grid)*grid,Mathf.Round(v.y/grid)*grid);}).ToArray()).ToList();var g=new G();
for(int side=0;side<2;side++){int start=g.p.Count;surfaceType=1;FillContours(g,loops,.39f,cream,1.3f);if(detailed)foreach(var loop in loops)for(int i=0;i<loop.Length;i++){var a=loop[i];var b=loop[(i+1)%loop.Length];g.Quad(new Vector3(a.x,a.y,.39f),new Vector3(a.x,a.y,-.12f),new Vector3(b.x,b.y,-.12f),new Vector3(b.x,b.y,.39f),gold,gold,gold,gold);}int segments=detailed?32:12;surfaceType=0;var ring=Enumerable.Range(0,segments+1).Select(i=>{float a=i*Mathf.PI*2/segments;return new Vector3(Mathf.Cos(a)*1.38f,2.45f+Mathf.Sin(a)*1.38f,.12f);}).ToList();Tube(g,ring,.060f,gold,4,detailed?6:4);var cup=new[]{new Vector2(-.72f,2.54f),new Vector2(.58f,2.54f),new Vector2(.49f,1.99f),new Vector2(.26f,1.81f),new Vector2(-.29f,1.81f),new Vector2(-.59f,2.01f)};surfaceType=1;FillContours(g,new List<Vector2[]>{cup},.33f,cream,2.6f);if(detailed)for(int i=0;i<cup.Length;i++){var a=cup[i];var b=cup[(i+1)%cup.Length];g.Quad(new Vector3(a.x,a.y,.33f),new Vector3(a.x,a.y,-.12f),new Vector3(b.x,b.y,-.12f),new Vector3(b.x,b.y,.33f),gold,gold,gold,gold);}surfaceType=0;Tube(g,new List<Vector3>{new Vector3(-.77f,1.68f,.33f),new Vector3(.75f,1.68f,.33f)},.05f,cream,3,detailed?6:4);int steps=detailed?10:5;var handle=Enumerable.Range(0,steps+1).Select(i=>{float a=-Mathf.PI*.5f+i*Mathf.PI/steps;return new Vector3(.57f+.36f*Mathf.Cos(a),2.28f+.25f*Mathf.Sin(a),.33f);}).ToList();Tube(g,handle,.060f,cream,3,detailed?6:4);foreach(float x in new[]{-.33f,0,.33f}){var steam=Enumerable.Range(0,steps+1).Select(i=>{float t=i/(float)steps;return new Vector3(x+.07f*Mathf.Sin(t*6.28f),2.73f+t*.62f,.33f);}).ToList();Tube(g,steam,.035f,cream,3,detailed?5:4);}if(side==1)for(int i=start;i<g.p.Count;i++)g.p[i]=Quaternion.Euler(0,180,0)*g.p[i];}
surfaceType=0;g.Box(Vector3.zero,new Vector3(10.1f,.13f,.17f),dark);g.Box(new Vector3(0,1.38f,0),new Vector3(.13f,4.5f,.17f),dark);foreach(float x in new[]{-1.2f,1.2f})g.Box(new Vector3(x,-.45f,0),new Vector3(.13f,.90f,.17f),dark);var mesh=new Mesh{name=detailed?"Coffee open raised cup and lettering near":"Coffee open raised cup and lettering far"};WriteG(mesh,g);UnityEngine.Object.DestroyImmediate(atlas);return mesh;}
